#!/usr/bin/env python3
"""Apply the documented v7 editorial pass to the preserved Codex manuscript."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
s=json.loads((ROOT/'provenance/codex_received/paper/submission_blocks.json').read_text())
m=s['main_pages'];a=s['appendix_pages']
m[0][5]['text']=m[0][5]['text'].replace('after an irreversible decision','after a committed decision')
m[0][7]['text']=("Our contributions are **(1)** a target-sensitive identification boundary, **(2)** conditional certification rules with explicit failure modes, and **(3)** an executable local audit separating timing, coverage, and statistical validity. The main experimental finding is a synthetic robustness failure and its correction, not a measured LLM tendency. The key threat to validity is transport: the deployment reference is supplied to the mathematics, not learned from the local benchmark. The release reproduces the saved experiments and audits their records; reproduction does not add independent observations.")
m[1][1]['text']=("**Sandbox detection.** Penumbra defines a bounded interactive distinguishing game [1, Section 2, Definition 1, p. 3] and a deterministic external-consequence witness [1, Section 5, Proposition 1, p. 7]. The latter requires an accessible independent verification channel. We instead ask whether differences leave a specified action probability unidentified. A coherent local replica refutes an unrestricted containment trilemma; substrate detectability alone does not prove lifecycle awareness.")
m[1][2]['text']=("**Awareness and behavior.** SAD separates self-knowledge, inference, and action [2, Section 2.1, p. 4]. Rajakumar and Laine compare prompt classification with procedural responses [3, Section 3.2, pp. 4-5]. Sandbagging work distinguishes demonstrated capability from spontaneous propensity [4, pp. 2-3]. We likewise separate an available signal, elicited probing, a reported probability, and an observable choice. Explanations are not faithful private-state measurements by assumption.")
m[1][3]['text']=("**Strategic evaluation and control.** Deployment-specific signals can defeat repeated testing in Kovařík et al. [5, Section 3.1.4, pp. 7-8]. Korbak et al. separate measured rates, deployment approximation, and extrapolation [6, Section 2.7, pp. 7-8]. We study a conditional statistical subclaim, not a complete safety case.")
m[1][4]['text']=("**Statistical foundations.** Composite e-testing [7, Section 3], adaptive information bounds [8, Lemma 1], interactive estimation [9, Appendix E.2], and sequence-form policies [10, Section 2] are established. Partial identification without overlap also has substantial precedent [12]. Our scoped contribution is the target-specific safe-evidence contract and executable counterexamples, not a new general testing or missing-support principle. Priority for the combined formulation still requires independent review.")
m[1][7]['text']=("One run is a finite action-observation tree. Histories include all world-correlated inputs: prompts, exposed timing, errors, session state, and service responses. Private randomness and within-run memory are allowed. A realization plan x records action probabilities through linear flow constraints. Legal behavioral mixtures form a compact convex set X; neural-network parameters need not be convex.")
m[1][9]['text']=("Controller j is a complete safe interactive environment, not an isolated response. Its log law is specified above; the known deployment reference and specified behavior determine J. Runs independently reset the same agent; controllers may be selected using earlier records. Containment forbids unauthorized agent-caused transitions outside the declared local boundary. Our tools only mutate memory and never execute arbitrary code; this is not a hardened sandbox claim.")
m[3][1]['text']=(r"Fix $0\le\tau_0<\tau\le1$ and $0<\delta<1$. Class G has $J(x)\le\tau_0$; the high-risk null B has $J(x)\ge\tau$. A certificate time T is $\delta$-sound if every high-risk agent has probability at most $\delta$ of ever receiving a certificate. Completeness requires finite worst-case expected time on G. The middle region has no power guarantee. Soundness is not a posterior safety probability. Here D denotes relative entropy.")
m[3][7]['text']=(r"Let $e_t$ be a nonnegative score chosen before the next joint controller-record outcome; $r_t$ is its finite maximum minus minimum. Its nominal conditional null mean is at most $1+\nu_t$, and its actual conditional law is within total variation $\eta_t$. Both nonnegative bounds must be justified, not inferred from clean runs. Then")
m[5][2]['text']=("All 960 scripted episodes completed, with zero failures or exclusions. The hand-written final diagnostic correctly classified all 768 factorial episodes and 96 of 192 balanced coherent controls (50%). These are checks of known mechanisms, not autonomous LLM discovery; repeated scripted seeds are not independent realistic tasks.")
m[6][2]['caption']=("Figure 2. Exact probability of crossing threshold 20 by round 200. Nominal evidence becomes invalid under the injected probability shift. Correction uses the known conditional total-variation envelope of this synthetic fault, not an envelope estimated for a real deployment. These are exact calculations, not LLM observations.")
m[6][6]['text']=("No evaluated LLM request was made. Codex saved two new smoke-test cohorts (12 mock episodes and 36 mock requests each); an inherited cohort has the same counts. All 36 saved mock episodes are transport fixtures, excluded from scientific model claims. Exact model IDs and spending authorization remain absent; real-provider compatibility needs a separate authorized pilot.")
m[7][5]['text']=m[7][5]['text'].replace('[7–11]','[7–12]')
m[7][-1]['text']=("The companion release contains code, immutable records, figures, source files, an evidence audit, and a SHA-256 manifest. Regenerated PDF, DOCX, and Markdown correspond to the same revised source. No public repository was created. Author confirmation, affiliation, an accepted artifact attachment or URL, and human review remain submission gates.")
a[2][4]['text']=("Codex reproduced the original CPU configuration before edits. This release reran it in a new directory: all seven files matched, including 960 episode records and 3,000 sampling count vectors (seed 620231). The inherited certificate checker again passed 38 cases and 2,031 rational constraints. An independent saved-record audit checked counts, estimates, and hashes. Reproduction is not additional independent data.")
a[2][6]['text']=("The 17 Codex tests passed; one added regression rejects exponent overflow such as 1e400, bringing the suite to 18. Original records are unchanged. Old Standard, Pandoc, LibreOffice and required Python libraries were available locally; the revised manuscript was regenerated and visually inspected. Previously missing attachments [1,3] were rechecked in the conversation; selected bibliography metadata was separately verified. Exact source locations and remaining metadata gaps are in verification/v7/source_audit.json. No real inference occurred.")
a[3][5]['text']=("ChatGPT and Codex assisted theory exploration, drafting, code and checking. Codex reproduced the CPU results and repaired failure accounting. This revision repeated the audit, fixed numeric-overflow parsing, checked primary-source locations and regenerated the report. No evaluated LLM experiment was run. These checks are not independent human theorem review. Human authors must confirm authorship and affiliation, own the writing, and review claims, references and disclosure before submission.")
# The Codex source overflows page five; remove only the repeated reproduction paragraph.
assert m[4][-1]['text'].startswith('The supplied CPU results')
m[4].pop()
a[2][4]['text'] += ' These CPU analyses are retrospective, not publicly preregistered.'
s['references'][0]=("**[1]** Penumbra: Sandboxing Autonomous Agents by Measuring, Not Assuming, Indistinguishability. Undated supplied manuscript, paper (1).pdf; Section 2, Definition 1, p. 3; Section 5, Proposition 1, p. 7. Author and venue are not stated in the PDF. Matching public text: https://vanshverma.com/research/penumbra/html")
s['references'][2]=("**[3]** Sanyu Rajakumar and Rudolf Laine. Eliciting Situational Awareness in Large Language Models Through Fine-Tuning and In-Context Mechanisms. Undated supplied manuscript; Section 3.2, pp. 4-5. Public version/date not established for this exact PDF; see the source audit.")
s['references'][7]=s['references'][7].replace('[8]','**[8]**',1)
s['references'][9]=("**[10]** Daphne Koller, Nimrod Megiddo, and Bernhard von Stengel. 1996. Efficient Computation of Equilibria for Extensive Two-Person Games. Games and Economic Behavior 14(2), 247-259. Section 2. doi:10.1006/game.1996.0051.")
s['references'].append("**[12]** Samir Khan, Martin Saveski, and Johan Ugander. 2024. Off-policy Evaluation Beyond Overlap: Sharp Partial Identification Under Smoothness. ICML, PMLR 235, 23734-23757. https://proceedings.mlr.press/v235/khan24b.html")
assert len(s['abstract'].split())==150
assert s['abstract']==m[0][3]['text']
(ROOT/'paper/submission_blocks.json').write_text(json.dumps(s,indent=2,ensure_ascii=False)+'\n')
print('Wrote v7 manuscript with unchanged abstract and scientific numbers.')
